tokenfield.script:
function onInit()
	local sValue=getValue();
	if sValue == nil or sValue == "" then
		setValue("button_char_inv_none");
	else
		sf.DebugOut("sVal:" .. sValue);
	end
end
function onDoubleClick()
	sf.DebugOut("sVal:" .. getValue() );
	setValue("button_char_inv_none");
end

buttoncontrol.script:
				function onInit()
				 	local sName = window.orgName.getValue();
					if sName == "" or sName == nil then
            window.orgName.setValue("<< NPC Org >>");
					  popup();
					end
				end
        function onButtonPress()
				  popup();
				end
				function popup()
					local sDBnode = window.getDatabaseNode();
          Debug.console("detail_orgs:ButtonExamine popup sDBnode=" .. tostring(sDBnode));
					Interface.openWindow("npc_org_popup", sDBnode);
				end

				function onInit()
				 	updateShare();
				end
        function onButtonPress()
				  updateShare();
				end
				function updateShare()
					local nValue = getValue();
          Debug.console("ButtonShare:onButtonPress nValue=" .. tostring(nValue));

          local sDBnode = window.getDatabaseNode();
          Debug.console("ButtonShare:onButtonPress sDBnode=" .. tostring(sDBnode));

          local sDBparent = sDBnode.getParent();
          Debug.console("ButtonShare:onButtonPress sDBparent=" .. tostring(sDBparent));

          -- default to private
          --window.setPublic(false);
          if nValue == 1 then
            --window.setPublic(true);
          end
				end
